var rooms = createRoomService(go, documents, getHocuspocus);
var review = createReviewService(rooms, go, documents, getHocuspocus);
var connections = createConnectionHandlers(rooms, go, config);
server = new Server(
  {
    name: "voex-collab",
    address: host,
    port,
    quiet: true,
    stopOnSignals: false,
    debounce: 1e3,
    maxDebounce: 5e3,
    timeout: 3e4,
    ...connections.hooks,
    ...createDocumentHooks(rooms, documents.snapshot),
    onRequest: createHttpHandler(config, rooms, review, go)
  },
  { maxPayload: MAX_MESSAGE, perMessageDeflate: false }
);
connections.attachSocketLimits(server);
var stopRevalidation = connections.startRevalidation();
